"""Technical results generated from code, not a submission slide deck."""
from pathlib import Path


def write_results(output: Path, metrics: dict, profiles, decision: dict, business: dict):
    rows = [
        "# Reproducible technical results", "",
        "Generated by `python run_model.py`. This is a technical record, not the team's submission slides.", "",
        f"Observations: {metrics['observation_count']}; training: {metrics['training_rows']}; test: {metrics['test_rows']}.",
        f"Test status: {metrics['test_evaluation_status']}.", "",
        "## Fit", "", "| Statistic | One-group baseline | v1 |", "| --- | ---: | ---: |",
        f"| Groups | 1 | {metrics['chosen_k']} |",
        f"| Training SSE | {metrics['baseline_train_sse']:.6f} | {metrics['model_train_sse']:.6f} |",
        f"| Training RMS distance | {metrics['baseline_train_rms_distance']:.6f} | {metrics['model_train_rms_distance']:.6f} |", "",
        f"Training SSE reduction: {metrics['training_sse_reduction_pct']:.4f}%. This is not medical accuracy or a clinical benefit.",
        f"Close training-elbow candidates: {metrics['elbow_selection']['near_tie_candidates']}.", "",
        "## Group summaries in original units", "",
        "| Group | People | Mean age | Mean duration | Mean HbA1c (%) | Mean systolic BP | Male share (%) | Relative burden |",
        "| --- | ---: | ---: | ---: | ---: | ---: | ---: | --- |",
    ]
    for _, p in profiles.iterrows():
        rows.append(f"| {p.segment_id} | {p['count']} | {p.age_years_mean:.2f} | {p.diabetes_duration_years_mean:.2f} | {p.hba1c_pct_mean:.2f} | {p.systolic_bp_mmhg_mean:.2f} | {p.male_share_pct:.2f} | {p.burden_tier} |")
    rows += ["", "The relative-burden order is an explicit equal-weight summary of standardized duration, HbA1c, and systolic-pressure cluster means. It is not an estimated future-risk probability or quality-of-life score.", "",
        "## Sensitivity", "",
        f"Adjusted Rand agreement with a fit excluding recorded sex/gender: {metrics['recorded_category_sensitivity_ari']:.6f} (1 means identical grouping).",
        f"Minimum adjusted Rand agreement across the five checked seeds: {metrics['random_seed_sensitivity']['minimum_ari']:.6f}.",
        f"Smallest training group: {metrics['smallest_training_cluster']} people. Small groups and close elbows limit interpretation.", "",
        "## New input and product decision", "",
        f"Example input is recorded in `examples/new_user.json`. Assigned group: {decision['segment_id']}; decision: {decision['decision']}.",
        "The decision changes the emphasis of eye-health information. Both standard and enhanced versions provide information; this does not decide whether someone needs an examination.", "",
        "## Hypothetical business scenario", "",
        f"Assume {business['assumptions']['monthly_users']} monthly users; generic-information navigation takes {business['assumptions']['generic_information_navigation_minutes']} minutes and enhanced-information navigation takes {business['assumptions']['enhanced_information_navigation_minutes']} minutes for recipients.",
        f"Assume the future group mix matches the training sample: enhanced-information share = {business['enhanced_information_training_users']}/{business['training_users']}.",
        f"Assumed total navigation minutes/month: {business['baseline_monthly_navigation_minutes']:.4f} baseline and {business['model_monthly_navigation_minutes']:.4f} v1; difference = {business['assumed_monthly_navigation_minutes_saved']:.4f} minutes.",
        "No time saving, treatment effect, or quality-of-life improvement was measured. These are labeled assignment assumptions.", "",
        "## Reproduction", "", "Every value above comes from the JSON/CSV outputs written by the same command. All comparisons are in-sample for the 29-person version. The separate retinal-findings file is a post-fit descriptive check, not a held-out validation set.", "",
    ]
    (output / "RESULTS.md").write_text("\n".join(rows), encoding="utf-8")
